'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const S={event:null,data:null,pass:null,admin:null,staff:null,me:null,page:'home',mode:'participant',rating:0,lang:localStorage.getItem('festival_lang')||'ko',booth:null,qr:null,filter:'',zone:'',mapBuilding:'',mapZoom:1,selectedMission:null,inquiry:null,survey:null,questions:[],templateNames:[],reports:[],analysis:null,poll:null};
let token=sessionStorage.getItem('festival_management_token')||'',toastTimer,modalUrl;
const states={open:'운영 중',paused:'일시 중단',closed:'운영 종료',received:'접수',confirmed:'확인',progress:'처리 중',resolved:'완료',ready:'발송 준비',requested:'발송 요청',sent:'발송 성공',failed:'발송 실패'};
const EN={'홈':'Home','프로그램':'Programs','미션':'Missions','안전':'Safety','내 참여':'My visit','지도·부스 찾기':'Map & booths','미션 보기':'Missions','전체 보기':'View all','위치 보기':'Location','상세 보기':'Details','평가 없이 인증':'Check in without rating','별점 남기고 인증':'Rate & check in','운영 중':'Open','일시 중단':'Paused','운영 종료':'Closed','설문 참여':'Event survey','참여 인증 완료':'Check-in complete','행사 전체 설문':'Event survey','문의처':'Contact','안내':'Guide','다른 언어 안내':'Other languages'};
const t=v=>S.lang==='en'?(EN[v]||v):v;
const icon=n=>{const p={home:'<path d="m3 10 9-7 9 7v10H3zM9 20v-7h6v7"/>',calendar:'<rect x="4" y="5" width="16" height="16" rx="2"/><path d="M8 2v6m8-6v6M4 11h16"/>',flag:'<path d="M5 22V3m0 1h14l-3 5 3 5H5"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z"/><path d="m8 12 3 3 5-6"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',map:'<path d="m3 5 6-2 6 2 6-2v17l-6 2-6-2-6 2zM9 3v17m6-15v17"/>',notice:'<path d="M4 10h4l10-5v14L8 14H4zM8 14l2 7M21 9v6"/>',clipboard:'<rect x="5" y="5" width="14" height="17" rx="2"/><rect x="8" y="2" width="8" height="5" rx="1"/><path d="M9 12h6m-6 4h6"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',back:'<path d="m14 5-7 7 7 7M7 12h14"/>',check:'<path d="m5 12 4 4L20 5"/>',chat:'<path d="M4 4h16v12H9l-5 5z"/><path d="M8 8h8m-8 4h5"/>',chart:'<path d="M4 3v18h18M8 16v-5m5 5V7m5 9V4"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m10 3-1 3-3 1-3 3v4l3 3 3 1 1 3h4l1-3 3-1 3-3v-4l-3-3-3-1-1-3z"/>'};return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${p[n]||p.flag}</svg>`};
const button=(label,action,cls='',extra='')=>`<button type="button" class="${cls}" data-action="${esc(action)}" ${extra}>${label}</button>`;
const note=s=>`<p class="muted">${s}</p>`;
const empty=s=>`<div class="empty">${s}</div>`;
const tag=(status)=>`<span class="tag ${status==='paused'?'pink':status==='closed'?'gray':''}">${esc(t(states[status]||status))}</span>`;
const field=(name,label,value='',type='text',required=false)=>`<label for="f-${name}">${esc(label)}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}>`;
const area=(name,label,value='',required=false)=>`<label for="f-${name}">${esc(label)}</label><textarea id="f-${name}" name="${name}" ${required?'required':''}>${esc(value)}</textarea>`;
const options=(items,value)=>items.map(([v,l])=>`<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(l)}</option>`).join('');
const select=(name,label,items,value)=>`<label for="f-${name}">${esc(label)}</label><select id="f-${name}" name="${name}">${options(items,value)}</select>`;
const check=(name,label,checked=false)=>`<label class="check"><input type="checkbox" name="${name}" ${checked?'checked':''}>${esc(label)}</label>`;
function toast(msg){$('#toast').textContent=msg;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,5000)}
async function api(path,method='GET',data){const res=await fetch(path,{method,headers:{...(data?{'Content-Type':'application/json'}:{}),...(token?{Authorization:'Bearer '+token}:{})},body:data?JSON.stringify(data):undefined});const ct=res.headers.get('Content-Type')||'';if(!ct.includes('json')){if(!res.ok)throw Error('요청 처리에 실패했습니다.');return res.blob()}const out=await res.json();if(res.headers.get('X-Festival-Offline')==='1'){S.offline=true;S.offlineAt=new Date().toISOString()}if(!res.ok)throw Error(out.error||'요청 실패');return out}
const ep=route=>'/api/events/'+encodeURIComponent(S.event)+'/'+route;
function modal(title,body){$('#modal').innerHTML=`<section class="modal-body" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-header"><h2>${esc(title)}</h2>${button('✕','close','','aria-label="닫기"')}</div>${body}</section>`;$('#modal').hidden=false;$('#modal button, #modal input')?.focus()}
function closeModal(){$('#modal').hidden=true;$('#modal').innerHTML='';if(modalUrl){URL.revokeObjectURL(modalUrl);modalUrl=null}}
function submitButton(text='저장'){return `<div class="form-actions"><button class="primary" type="submit">${esc(text)}</button></div>`}
function form(type,body,id=''){return `<form data-form="${type}" data-id="${esc(id)}">${body}</form>`}
function timeLabel(v){try{return new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(v))}catch{return v}}
function intro(){return `<aside class="intro"><div class="wordmark">PEOPLE · PLACE · EXPERIENCE</div><h1>새로운 경험을 만나고,<br><em>함께 만드는 내일.</em></h1><p>부스를 둘러보고, 미션을 완성하고,<br>나만의 박람회 이야기를 만나보세요.</p><div style="margin:35px 0"><i class="orb"></i><i class="orb" style="width:35px;height:35px"></i></div><div class="intro-links"><a href="/manage">운영본부</a><a href="/booth">부스 관리</a><a href="/register?event=${encodeURIComponent(S.event||'')}">부스 등록</a></div></aside>`}
const navItems=[['home','홈','home'],['programs','프로그램','calendar'],['missions','미션','flag'],['safety','안전','shield'],['mine','내 참여','user']];
function publicShell(content){const event=S.data?.event;const notices=(S.data?.notices||[]).filter(n=>n.severity==='urgent');$('#app').innerHTML=`<div class="app-wrap">${intro()}<section class="device"><header class="app-header"><strong>${esc(S.page==='home'?'청소년박람회':({'programs':t('프로그램'),'map':'지도·부스','booth':'부스 안내','certify':'부스 참여','missions':t('미션'),'safety':t('안전'),'mine':t('내 참여'),'survey':t('행사 전체 설문'),'report':'안전 신고','certified':t('참여 인증 완료')})[S.page]||event?.name)}</strong><div class="tools">${button(S.lang==='ko'?'한국어 / EN':'EN / 한국어','language','lang')}${button(icon('notice'),'other-languages','icon-btn','aria-label="다른 언어 안내"')}</div></header>${notices.map(n=>`<div class="public-alert"><strong>${esc(n.title)}</strong> · ${esc(n.body)}</div>`).join('')}<main class="page ${S.page==='home'?'home':''}">${S.offline||!navigator.onLine?'<div class="notice">오프라인 · 저장된 안내입니다. 운영 상태·공지·지도는 최신 정보가 아닐 수 있습니다.</div>':''}${content}</main><nav class="nav" aria-label="참가자 메뉴">${navItems.map(([p,label,i])=>button(icon(i)+`<span>${esc(t(label))}</span>`,'nav:'+p,p===S.page?'active':'')).join('')}</nav></section></div>`;document.documentElement.lang=S.lang;document.title=(event?.name||'행사')+' · '+t(navItems.find(n=>n[0]===S.page)?.[1]||'안내');applyTheme()}
function applyTheme(){const theme=S.data?.theme||S.admin?.event?.settings||{};for(const [css,key]of [['--blue','primary'],['--cyan','accent']])if(/^#[a-f0-9]{6}$/i.test(theme[key]||''))document.documentElement.style.setProperty(css,theme[key]);const hero=$('.hero');if(hero&&/^\/assets\/[\w.-]+$/.test(theme.hero||''))hero.style.backgroundImage=`url('${theme.hero}')`}
async function loadPublic(){S.data=await api('/api/events/'+S.event);try{S.pass=await api(ep('pass'))}catch(e){if(navigator.onLine)throw e;S.pass={participant:null,visits:[],missions:[],reports:[]}}}
async function ensurePass(){if(S.pass?.participant)return true; if(!localStorage.getItem('festival_notice_ack')){modal('참여 기록 안내',`<p>참여 기록은 현재 기기와 브라우저에 연결됩니다. 기기·브라우저를 바꾸거나 브라우저 데이터를 삭제하면 기록을 이어서 이용하기 어려우며, 별도의 복구 기능은 제공하지 않습니다.</p>${note('시크릿 모드 이용은 피하고 설문까지 같은 브라우저를 사용해 주세요. 임의 식별자와 활동 기록도 개인정보에 해당할 수 있습니다. 이름·생년월일·연락처는 초기 참여에서 요구하지 않습니다.')}${button('확인하고 계속','ack-pass','primary full')}`);return false}S.pass=await api(ep('pass'),'POST',{});return true}
function hero(){const e=S.data.event;const sample=S.data.theme.sample;return `<section class="hero"><div class="hero-copy"><span class="edition">${sample?'제22회':'함께하는 축제'}</span><h1>${sample?'대한민국<br>청소년박람회':esc(e.name)}</h1><span class="slogan">${esc(e.description||'함께 만드는 특별한 하루')}</span><div class="meta">${esc(e.start)} — ${esc(e.end)}<br>${esc(e.venue)}</div>${sample?'<span class="sample">샘플 행사 · 날짜는 개발 검증용</span>':''}</div></section>`}
function miniProgram(p){return `<button class="program-mini" data-action="program:${esc(p.id)}"><span class="mini-meta">${esc(p.time)} <span class="tag ${p.category==='공연'?'pink':'blue'}">${esc(p.category)}</span></span><strong>${esc(p.title)}</strong><span class="muted" style="font-size:10px">⌖ ${esc(p.place)}</span></button>`}
function home(){const ns=S.data.notices.filter(n=>n.severity!=='urgent');return `${hero()}${ns.length?`<div class="notice">${icon('notice')} ${esc(ns[0].title)} ${button('보기','notices','text-btn')}</div>`:''}<div class="shortcuts">${button(icon('map')+'<span><strong>'+t('지도·부스 찾기')+'</strong><small>행사장 위치 안내</small></span>','nav:map','shortcut map')}${button(icon('flag')+'<span><strong>'+t('미션 보기')+'</strong><small>체험하고 미션을 완성해요</small></span>','nav:missions','shortcut mission')}</div><div class="section-head"><h3>오늘의 프로그램</h3>${button(t('전체 보기')+' ›','nav:programs','text-btn')}</div><div class="program-grid">${S.data.programs.slice(0,2).map(miniProgram).join('')}</div>${!S.data.programs.length?empty('등록된 프로그램이 없습니다.'):''}${button(icon('clipboard')+'<span><strong>박람회는 어떠셨나요?</strong><small>설문 참여 조건과 추첨 응모를 확인하세요.</small></span>','nav:survey','survey-link')}<div class="section-head"><h3>행사 안내</h3></div>${note(esc(S.data.event.venue))}<div class="row">${button('안전·편의시설','nav:safety','text-btn')}${button('전체 공지','notices','text-btn')}${button('행사 선택','choose-event','text-btn')}</div>${note('같은 기기·브라우저로 이용해 주세요. 기록 복구는 제공하지 않습니다.')}${S.lang==='en'?'<div class="hint">Event content is currently in Korean. Translation API is not configured. Use your browser’s page translation for untranslated text.</div>':''}`}
function programs(){const dates=[...new Set(S.data.programs.map(p=>p.date))];return `<h2>${t('프로그램')}</h2><div class="chips">${button('전체','program-date:',''+(!S.filter?'active':''))}${dates.map(d=>button(esc(d),'program-date:'+d,S.filter===d?'active':'')).join('')}</div>${note('자유 참여·현장 접수·외부 신청 방법은 프로그램 상세에서 확인하세요. 앱 내 예약은 제공하지 않습니다.')}${S.data.programs.filter(p=>!S.filter||p.date===S.filter).map(p=>`<div class="card"><span class="tag blue">${esc(p.category)}</span><h3 style="margin-top:10px">${esc(p.title)}</h3><p>${esc(p.date)} · ${esc(p.time)}<br>${esc(p.place)}</p><div class="actions">${button('상세 안내','program:'+p.id)}${button(t('위치 보기'),'program-location:'+p.id)}</div>${button('♡ 관심 일정 저장','bookmark:'+p.id,'text-btn')}</div>`).join('')||empty('프로그램이 없습니다.')}`}
function boothList(){return S.data.booths.filter(b=>(!S.zone||b.zone===S.zone)&&(!S.filter||[b.name,b.organization,b.description,b.code].some(v=>(v||'').includes(S.filter))))}
function mapPage(){const buildings=S.data.theme.building_maps||[];const map=buildings.find(x=>x.name===S.mapBuilding)||buildings[0];const bs=boothList();return `<div class="search">${icon('search')}<input id="booth-search" aria-label="부스 검색" placeholder="부스명·기관명·체험 내용 검색" value="${esc(S.filter)}"></div><div class="filters"><select id="zone-filter" aria-label="존 선택">${options([['','전체 존'],...S.data.zones.map(z=>[z.id,z.name])],S.zone)}</select><select id="building-filter" aria-label="지도 선택">${options([['outdoor','야외 길찾기'],...buildings.map(m=>[m.name,m.name])],S.mapBuilding||map?.name||'outdoor')}</select></div>${S.mapBuilding==='outdoor'||!map?outdoorPage():`<div class="map-label">건물별 통합 평면도 · 층 선택 없이 한 화면에서 확인</div><div class="map-scale">${button('−','zoom:-')}${button('전체 보기','zoom:reset')}${button('+','zoom:+')}</div><div class="map-canvas"><div class="map-inner" style="width:${100*S.mapZoom}%"><img src="${esc(map.image)}" alt="${esc(map.name)} 통합 평면도">${bs.filter(b=>b.building===map.name).map(b=>`<button class="map-marker ${S.booth?.id===b.id?'active':''}" style="left:${Number(b.x)}%;top:${Number(b.y)}%" data-action="booth:${esc(b.id)}">${esc(b.code||b.name)}</button>`).join('')}</div></div>`}<div class="section-head"><h3>부스 목록 <small>${bs.length}곳</small></h3></div>${bs.map(b=>`<div class="card"><div class="row">${tag(b.status)}<small>${esc(b.zone_name)} · ${esc(b.code)}</small></div><h3 style="margin-top:12px">${esc(b.name)}</h3>${note(esc(b.organization))}${button(t('상세 보기'),'booth:'+b.id)}</div>`).join('')||empty('조건에 맞는 부스가 없습니다.')}`}
function outdoorPage(){const nodes=S.data.theme.outdoor_nodes||[];return `<div class="card"><h3>야외 길찾기</h3>${note('위성지도 제공사는 아직 연결되지 않았습니다. 운영자가 등록한 보행로가 있으면 지점 간 경로와 거리를 확인할 수 있습니다.')}<div class="map-canvas" id="outdoor-canvas"><div class="plan-placeholder">${nodes.length?'등록된 보행 지점 기반 경로 안내':'아직 보행로가 등록되지 않았습니다.'}</div></div>${select('route-from','출발지',nodes.map(n=>[n.id,n.name]),'')}${select('route-to','도착지',nodes.map(n=>[n.id,n.name]),'')}<div class="actions">${button('경로 계산','route','primary',nodes.length?'':'disabled')}${button('GPS 위치 확인','gps')}</div><div id="route-result"></div>${note('GPS 위치는 참가자 동의 시 기기에서만 확인합니다. 실제 보행로를 따라 안내하며 현장 통행 제한을 우선하세요.')}</div>`}
function boothDetail(){const b=S.booth;if(!b)return empty('부스를 선택하세요.');return `${button('← 지도·부스','nav:map','back')}<div class="row">${tag(b.status)}<small>${esc(b.zone_name)} · ${esc(b.code)}</small></div><h2 style="margin-top:18px">${esc(b.name)}</h2><p>${esc(b.description)}</p><div class="card"><h3>이용 안내</h3><p>${esc(b.organization)}<br>${esc(b.building||'야외')} · ${esc(b.code)}</p>${button(t('위치 보기'),'location:'+b.id,'primary')}</div><div class="card"><h3>관련 미션</h3>${(S.pass?.missions||[]).filter(m=>m.kind==='booths'&&(!m.refs.length||m.refs.includes(b.id))||m.kind==='zone'&&m.refs.includes(b.zone)||m.kind==='zones').map(m=>`<p>${button(esc(m.title),'mission:'+m.id,'text-btn')}</p>`).join('')||note('연결된 미션이 없습니다.')}</div>${note('참여 인증은 체험 후 현장에 비치된 부스 QR을 스캔해 주세요.')}`}
function stars(){return `<div class="stars" role="group" aria-label="별점 선택">${[1,2,3,4,5].map(n=>button(n<=S.rating?'★':'☆','rate:'+n,n<=S.rating?'chosen':'',`aria-label="${n}점" aria-pressed="${n===S.rating}"`)).join('')}</div>`}
function certify(){const b=S.booth;const v=S.pass?.visits?.find(v=>v.booth===b?.id);if(!b)return empty('QR 정보를 확인하고 있습니다.');if(b.status!=='open'||S.data.event.status!=='active')return `${tag(b.status)}<h2 style="margin-top:20px">${esc(b.name)}</h2><div class="notice">현재 인증할 수 없습니다. 운영 상태와 행사 기간을 확인해 주세요.</div>`;return `<div class="score">${tag(b.status)}<h2 style="margin-top:15px">${esc(b.name)}</h2>${note(esc(b.code||''))}${v?'<div class="notice info">이미 인증한 부스입니다. 다시 제출해도 참여 수는 늘어나지 않습니다.</div>':''}<h3 style="margin-top:35px">체험은 어떠셨나요?</h3>${stars()}${note('평가는 선택 사항입니다. 점수와 관계없이 동일하게 참여를 인정합니다.')}</div>${button(t('별점 남기고 인증'),'certify','primary full',S.rating?'':'disabled')}<p>${button(t('평가 없이 인증'),'certify-skip','full')}</p>${note('제출이 완료되면 관련 미션에도 자동 반영됩니다.')}`}
function certified(){return `<div class="score"><div style="font-size:48px;color:var(--cyan)">✓</div><h2>${t('참여 인증 완료')}</h2><p>${esc(S.booth?.name)}</p></div>${(S.pass?.missions||[]).filter(m=>m.kind!=='text'&&m.kind!=='quiz').map(m=>`<div class="card"><h3>${esc(m.title)}</h3><p>${m.progress} / ${m.target} ${m.completed?'· 완료':''}</p><progress value="${m.progress}" max="${m.target}"></progress></div>`).join('')}<div class="actions">${button('다른 부스 찾기','nav:map')}${button(t('미션 보기'),'nav:missions','primary')}</div>${button(t('설문 참여'),'nav:survey','full')}`}
function missionPage(){const ms=S.pass?.missions||[];return `<div class="mission-hero"><h2>체험하고,<br>미션을 완성해요</h2><p>부스 QR 인증 시 자동으로 반영됩니다.</p></div>${ms.map(m=>`<div class="card"><div class="row"><span class="tag ${m.completed?'':'blue'}">${m.completed?'완료':m.pending?'검토 대기':m.available?'수행 가능':'기간 외'}</span></div><h3 style="margin-top:12px">${esc(m.title)}</h3><p>${esc(m.description)}</p><p>${m.progress} / ${m.target}</p><progress value="${m.progress}" max="${m.target}"></progress>${button('수행 조건 보기','mission:'+m.id,'text-btn')}</div>`).join('')||empty('공개된 미션이 없습니다.')}`}
function surveyPage(){if(!S.survey?.survey)return empty('아직 공개된 설문이 없습니다.');const {survey:s,can_respond,can_enter,open}=S.survey;if(!open)return empty('설문이 마감되었습니다.');if(!can_respond)return `<div class="notice">설문 참여 조건을 먼저 달성해 주세요.</div>${button('미션 확인','nav:missions','primary')}`;if(S.pass?.survey?.submitted)return `<div class="score"><h2>설문 제출 완료</h2></div><div class="notice info">${S.pass.survey.entry?'응모가 접수되었습니다.':'현재 패스의 응모 내역이 없습니다. 제출 당시 자격·연락처 중복 여부에 따라 응모에서 제외될 수 있습니다.'}</div>${button('내 참여','nav:mine','primary full')}`;return `<h2>${esc(s.title)}</h2><div class="wizard"><span class="step active"></span><span class="step active"></span><span class="step active"></span></div>${note('공통 설문 · 모르는 수치는 비워두세요. 실제 지출은 본인 부담분만 입력해 공동 지출의 중복을 줄여주세요.')}<form data-form="participant-survey">${select('age_group','연령 구분',[['','선택하세요'],['14plus','만 14세 이상'],['under14','만 14세 미만']],'')}<div id="child-notice"></div>${s.questions.map(q=>questionInput(q)).join('')}<div class="card"><h3>개인정보 수집·이용 안내</h3><p style="white-space:pre-wrap">${esc(s.consent)}</p>${check('survey_consent','설문 개인정보 안내를 확인하고 동의합니다.')}</div><div class="card"><h3>추첨 응모 · 선택</h3>${note(can_enter?'응모 조건을 충족했습니다.':'현재 미션 응모 조건을 충족하지 못했습니다. 설문 제출과 응모는 구분됩니다.')}${field('phone','당첨 연락을 받을 휴대전화 번호','','tel')}${field('phone_check','연락처 다시 입력','','tel')}${check('lottery_consent','위 안내의 추첨 연락처 수집·이용에 동의합니다.')}${note('같은 연락처는 최초 유효 응모 1건만 인정합니다. 보호자 번호를 공유해도 응모 기회는 한 번입니다.')}</div>${submitButton('확인 후 제출')}</form>`}
function questionInput(q){const required=q.required?'required':'';const label=`<label>${esc(q.label)} ${q.required?'<span class="field-error">*</span>':''}</label>`;let input='';if(q.type==='choice')input=`<select name="q_${esc(q.id)}" ${required}>${options([['','선택하세요'],...q.options.map(v=>[v,v])],'')}</select>`;else if(q.type==='multi')input=q.options.map(v=>`<label class="check"><input type="checkbox" name="q_${esc(q.id)}" value="${esc(v)}">${esc(v)}</label>`).join('');else if(q.type==='rating')input=`<select name="q_${esc(q.id)}" ${required}>${options([['','선택하세요'],...[1,2,3,4,5].map(n=>[n,n+'점'])],'')}</select>`;else if(q.type==='number')input=`<input name="q_${esc(q.id)}" type="number" min="0" max="1000000000" step="any" ${required}>`;else input=`<textarea name="q_${esc(q.id)}" maxlength="3000" ${required}></textarea>`;return `<div class="question">${label}${input}</div>`}
function safety(){const phone=S.data.theme.safety_phone;return `<h2>${t('안전')}</h2><div class="weather"><span style="font-size:33px">☁</span><div><strong>날씨 연결 전</strong><br><small>공식 기상정보를 확인해 주세요.</small></div></div><div class="notice urgent">급박한 위험에는 앱 답변을 기다리지 말고 전화로 도움을 요청하세요.</div><div class="emergency"><a href="tel:119">119<small>긴급 구조·구급</small></a><a href="tel:112">112<small>긴급 경찰 신고</small></a></div><div class="card"><h3>현장 안전본부</h3>${phone?`<a href="tel:${esc(phone.replace(/[^\d+]/g,''))}">${esc(phone)}</a>`:note('행사 운영자가 연락처를 등록하면 표시됩니다.')}</div><div class="card"><h3>안전시설·행동요령</h3>${button('지도에서 위치 확인','nav:map')}${note('의료실·AED·비상구·대피 집결지를 확인하고 현장 안내에 따라 이동하세요. 현장 방송과 안전요원의 지시를 우선하세요.')}</div><h3>신고·도움 요청</h3>${[['safety','위험·도움 요청'],['harassment','성희롱·성폭력 신고'],['camera','불법촬영·의심 기기 신고']].map(([v,l])=>`<p>${button(l,'report:'+v,'full')}</p>`).join('')}${!S.data.theme.reporting_enabled?note('현재 앱 신고 접수는 비활성화되어 있습니다. 긴급 연락처 또는 현장 안전본부를 이용하세요.'):''}`}
function reportPage(){const names={safety:'위험·도움 요청',harassment:'성희롱·성폭력 신고',camera:'불법촬영·의심 기기 신고'};return `${button('← 안전','nav:safety','back')}<h2>${names[S.reportKind]}</h2><div class="notice urgent">급박한 위험에는 112·119에 전화하세요. 증거가 없어도 접수할 수 있습니다. 의심 기기를 직접 만지거나 해체하지 마세요.</div>${!S.data.theme.reporting_enabled?empty('안전 대응 담당자·운영 절차 준비 후 접수 기능을 제공합니다.'):form('report',`${field('location','위치 · 건물·층·주변 부스','', 'text',true)}${area('body','현재 상황 · 불필요한 개인정보는 적지 마세요.','',true)}${note('이 화면은 선택 연락처·사진을 수집하지 않습니다. 동일 기기에서 운영본부 답변을 확인할 수 있으며 복구는 제공하지 않습니다.')}${submitButton('신고 접수')}`)}${button('빠르게 나가기','nav:home','text-btn')}${note('빠르게 나가도 브라우저 방문 기록은 삭제되지 않습니다.')}`}
function mine(){const p=S.pass;const bookmarks=JSON.parse(localStorage.getItem('festival_bookmarks_'+S.event)||'[]');return `<h2>${t('내 참여')}</h2>${p?.participant?`<div class="pass-card"><small style="color:white">${esc(S.data.event.name)}</small><strong>MY PASS</strong><code>${esc(p.participant.id.slice(0,12))}</code></div>`:`<div class="card"><h3>아직 참여 기록이 없습니다.</h3><p>부스 QR 인증 등 기록이 필요한 시점에 참가 패스가 생성됩니다.</p></div>`}<div class="stats"><div class="stat"><small>인증 부스</small><strong>${p?.visits.length||0}</strong></div><div class="stat"><small>완료 미션</small><strong>${p?.missions.filter(m=>m.completed).length||0}</strong></div><div class="stat"><small>저장한 일정</small><strong>${bookmarks.length}</strong></div></div><div class="card"><h3>설문·추첨</h3><p>${p?.survey?.submitted?'설문 제출 완료':'설문 미제출'}</p><p>${p?.survey?.entry?(p.survey.entry.prize?'당첨 · '+esc(p.survey.entry.prize)+' · '+esc(states[p.survey.entry.delivery]||''):'응모 완료 · 추첨 결과 대기'):'유효 응모 내역 없음'}</p>${button('설문 안내','nav:survey')}</div>${bookmarks.length?`<div class="card"><h3>관심 일정</h3>${S.data.programs.filter(x=>bookmarks.includes(x.id)).map(x=>`<p>${button(esc(x.title),'program:'+x.id,'text-btn')}</p>`).join('')}</div>`:''}<div class="card"><h3>인증한 부스</h3>${p?.visits.map(v=>`<p>${esc(v.code)} · ${esc(v.name)} ${v.rating?'★ '+v.rating:''}</p>`).join('')||note('인증 기록이 없습니다.')}</div>${p?.reports.length?`<div class="card"><h3>내 신고 처리 상태</h3>${p.reports.map(r=>`<div class="bubble"><small>${esc(r.id.slice(0,8))} · ${esc(states[r.status])}</small>${esc(r.reply||'답변을 기다리고 있습니다.')}</div>`).join('')}</div>`:''}<div class="notice info">같은 기기·브라우저를 이용해 주세요. 기록 복구 기능은 제공하지 않습니다.</div>`}
async function publicRender(){const pages={home,programs,map:mapPage,booth:boothDetail,certify,certified,missions:missionPage,safety,mine,survey:surveyPage,report:reportPage};publicShell((pages[S.page]||home)())}
async function navigate(page){closeModal();S.page=page;S.filter='';if(page==='survey'){if(!await ensurePass())return;S.survey=await api(ep('survey'))}if(['mine','missions'].includes(page))S.pass=await api(ep('pass'));await publicRender();window.scrollTo({top:0,behavior:'smooth'})}
function loginView(setup=false){$('#app').innerHTML=`<section class="login"><div class="brand">FESTIVAL OPERATIONS</div><h1>${setup?'첫 관리자 설정':'운영본부 로그인'}</h1>${note(setup?'로컬 개발 환경의 최초 관리자입니다. 배포 전 접근 제한과 HTTPS를 구성하세요.':'초대받은 개인 계정으로 접속합니다. 부스는 별도의 공동 관리 인증을 사용합니다.')}${form(setup?'setup':'login',`${field('email','이메일','','email',true)}${setup?field('name','담당자 표시명','','text',true):''}${field('password','비밀번호'+(setup?' · 12자 이상':''),'','password',true)}${submitButton(setup?'관리자 생성':'로그인')}`)}<div class="row" style="margin-top:20px"><a href="/">참가자 화면</a><a href="/booth">부스 관리</a></div></section>`}
function staffLogin(){const manager=location.pathname.startsWith('/bm/')?location.pathname.split('/')[2]:new URLSearchParams(location.search).get('manager')||'';$('#app').innerHTML=`<section class="login"><div class="brand">BOOTH WORKSPACE</div><h1>부스 공동 관리</h1>${note('관리 전용 주소와 공통 비밀번호로 여러 담당자가 함께 접속할 수 있습니다.')}${form('booth-login',`${field('manager','관리 코드',manager,'text',true)}${field('password','공통 비밀번호','','password',true)}${field('display','이번 접속 담당자 표시명','','text',true)}${submitButton('부스 관리 시작')}`)}<p><a href="/register">부스 새로 등록</a> · <a href="/">참가자 화면</a></p></section>`}
async function registerView(){const events=await api('/api/events');S.event=new URLSearchParams(location.search).get('event')||events[0]?.id;if(!S.event){$('#app').innerHTML=empty('등록 가능한 행사가 없습니다.');return}const data=await api('/api/events/'+S.event);$('#app').innerHTML=`<section class="login"><div class="brand">BOOTH REGISTRATION</div><h1>부스 등록</h1><p>${esc(data.event.name)}</p>${form('booth-register',`${select('zone','소속 존',data.zones.map(z=>[z.id,z.name]),'')}${field('name','부스명','','text',true)}${field('organization','운영 기관·단체')}${area('description','소개·체험 내용','',true)}${field('contact','운영 연락처 · 참가자에게 비공개')}${field('password','공통 관리 비밀번호 · 10자 이상','','password',true)}${note('제출 후 운영자 검토를 거쳐 공개됩니다. 담당자 연락처는 운영 목적으로만 사용합니다. 행사별 수집 안내를 확인한 뒤 제출하세요.')}${check('consent','부스 운영을 위한 담당 정보 제출에 동의합니다.')}${submitButton('등록 신청')}`)}<p><a href="/booth">기존 부스 관리</a></p></section>`}
async function inviteView(){const invite=new URLSearchParams(location.search).get('code')||'';$('#app').innerHTML=`<section class="login"><h1>운영본부 초대 수락</h1>${form('invite',`${field('invite','초대 코드',invite,'text',true)}${field('name','표시명','','text',true)}${field('password','신규 비밀번호 또는 기존 계정 비밀번호','','password',true)}${submitButton('초대 수락')}`)}</section>`}
const adminNav=[['dashboard','대시보드','chart'],['booths','공간·부스','map'],['content','콘텐츠·일정','calendar'],['missions','미션·설문','flag'],['draw','추첨·지급','clipboard'],['messages','소통·대응','chat'],['safety','안전','shield'],['reports','보고서','chart'],['settings','행사 설정','settings']];
async function refreshAdmin(){S.admin=await api(ep('admin'))}
function adminShell(content){$('#app').innerHTML=`<section class="admin"><aside class="sidebar"><small>FESTIVAL WORKSPACE</small><h2>행사 운영본부</h2><nav class="sidebar-nav">${adminNav.map(([p,l,i])=>button(icon(i)+esc(l),'admin-nav:'+p,S.page===p?'active':'')).join('')}</nav><div class="bottom">${button('새 행사 개설','new-event')}${button('참가자 화면','open-event')}${button('로그아웃','logout')}</div></aside><div class="admin-main"><header class="admin-top"><select id="event-switch" aria-label="관리 행사 선택">${options(S.me.events.map(e=>[e.id,e.name]),S.event)}</select><span class="muted">${esc(S.me.user.name)} · ${S.admin.roles.map(esc).join(', ')} ${button('갱신','admin-refresh','text-btn')}</span></header><main class="admin-page">${content}</main></div></section>`;applyTheme()}
function stat(label,v,unit=''){return `<div class="stat"><small>${esc(label)}</small><strong>${v??'—'}<span class="unit">${esc(unit)}</span></strong></div>`}
function boothTable(bs){return `<div class="scroll"><table><thead><tr><th>존 / 부스</th><th>오늘</th><th>행사 누적</th><th>평균 / 평가 수</th><th>승인</th><th>운영 상태</th><th>관리</th></tr></thead><tbody>${bs.map(b=>`<tr><td>${esc(b.zone_name)}<br><strong>${esc(b.code)} ${esc(b.name)}</strong></td><td>${b.today}</td><td>${b.total}</td><td>${b.ratings.average??'—'} / ${b.ratings.count}</td><td>${b.approved?'승인':'검토 대기'}</td><td>${tag(b.status)}</td><td>${button('수정','edit-booth:'+b.id)} ${button('QR·접근','booth-access:'+b.id)}</td></tr>`).join('')}</tbody></table></div>`}
function dashboard(){const a=S.admin;return `<h1>현장 운영 현황</h1>${note('Asia/Seoul · '+timeLabel(new Date().toISOString())+' 갱신 · 인증 집계는 실제 체류 인원이 아닙니다.')}${a.event.settings.sample?'<div class="notice info">샘플 행사입니다. 참여 수치는 실제 테스트 인증부터 누적됩니다. 부스 관리 비밀번호는 관리자가 새로 설정해야 합니다.</div>':''}<div class="stats">${stat('부스 참여 합계',a.stats.booth_total,'건')}${stat('고유 인증 패스',a.stats.certified,'패스')}${stat('설문 제출',a.stats.responses,'건')}${stat('유효 응모',a.stats.entries,'건')}</div><div class="section-head"><h3>존별 참여 합계</h3>${button('부스 CSV','export:booths','text-btn')}</div>${note('소속 부스별 참여자 합계 · 부스 간 중복 포함')}<div class="grid3">${a.zones.map(z=>`<div class="zone-card" style="border-top:3px solid ${esc(z.color)}"><h3>${esc(z.name)}</h3><strong>${z.total}<small>행사 누적 · 오늘 ${z.today}</small></strong></div>`).join('')}</div><div class="card"><h3>부스 운영 현황</h3>${boothTable(a.booths)}</div><div class="grid2"><div class="card"><h3>미처리 문의</h3>${a.inquiries.filter(i=>i.status!=='resolved').slice(0,5).map(i=>`<p>${button(esc(i.booth_name)+' · '+esc(i.category),'inquiry:'+i.id,'text-btn')}</p>`).join('')||note('미처리 문의가 없습니다.')}</div><div class="card"><h3>업무 알림 확인</h3>${a.notices.filter(n=>n.target!=='public').slice(0,4).map(n=>`<p>${esc(n.title)}<br><small>확인 ${n.confirmed.length} / ${n.target_count} 부스</small></p>`).join('')||note('발행된 업무 알림이 없습니다.')}</div></div>`}
function boothsAdmin(){return `<h1>공간·부스 관리</h1><div class="actions">${button('존 추가','add-zone','primary')}${button('부스 등록 링크','registration-link')}${button('통합 지도 편집','map-editor')}</div><div class="card"><div class="filters"><input id="admin-booth-search" placeholder="부스명 검색" aria-label="부스명 검색"><select id="admin-zone-filter" aria-label="존 필터">${options([['','전체 존'],...S.admin.zones.map(z=>[z.id,z.name])],'')}</select></div><div id="booth-table">${boothTable(S.admin.booths)}</div></div>${note('기존 부스의 존·위치를 변경하면 조회 시 현재 소속 존으로 합계가 표시됩니다. 인증 당시 존은 별도 보존되며, 과거 귀속 보고서의 상세 기준은 추가 설계 대상입니다.')}`}
function contentAdmin(){return `<h1>공지·프로그램</h1><div class="actions">${button('전체 공지 작성','add-public-notice','primary')}${button('프로그램 추가','add-program')}</div><div class="grid2"><div class="card"><h3>전체 공지</h3>${S.admin.notices.filter(n=>n.target==='public').map(n=>`<div class="bubble"><strong>${esc(n.title)}</strong><p>${esc(n.body)}</p><small>${esc(n.severity)} · ${timeLabel(n.created)}</small></div>`).join('')||note('공지 없음')}</div><div class="card"><h3>프로그램 일정</h3>${S.admin.programs.map(p=>`<div class="bubble"><strong>${esc(p.title)}</strong><p>${esc(p.date)} ${esc(p.time)} · ${esc(p.place)}</p></div>`).join('')||note('등록된 프로그램 없음')}${note('예약·좌석 관리 없이 참여 방법과 장소를 안내합니다.')}</div></div>`}
function missionsAdmin(){const a=S.admin;return `<h1>미션·전체 설문</h1><div class="grid2"><div class="card"><div class="section-head" style="margin-top:0"><h3>미션</h3>${button('미션 추가','add-mission','primary')}</div>${a.missions.map(m=>`<div class="bubble"><strong>${esc(m.title)}</strong><p>${esc(m.kind)} · 목표 ${m.target} · ${m.published?'공개':'비공개'}</p></div>`).join('')}${button('제출형 미션 검토','review-missions')}</div><div class="card"><h3>행사 전체 설문</h3><p>${a.survey?esc(a.survey.title):'미개설'}</p><p>${a.survey?.questions.length||0}문항 · ${a.survey?.published?'공개':'비공개'}</p>${button('설문 편집·표준양식','edit-survey','primary')}${note('응답 접수 후에는 문항을 변경할 수 없습니다. 연락처와 미성년자 동의 절차는 별도로 검토해야 합니다.')}</div></div>`}
function drawAdmin(){const a=S.admin;return `<h1>추첨·모바일 상품권</h1><div class="notice info">동일 연락처 최초 유효 응모 1건만 인정합니다. 응모 마감일 이후 추첨할 수 있습니다.</div><div class="stats">${stat('설문 제출',a.stats.responses)}${stat('유효 응모',a.stats.entries)}${stat('당첨 기록',a.winners.length)}</div><div class="actions">${button('상품 등록','add-prize','primary')}${button('발송용 CSV 다운로드','export:winners')}</div>${a.prizes.map(p=>`<div class="card"><div class="row"><h3>${esc(p.name)}</h3><span class="tag ${p.drawn?'':'blue'}">${p.drawn?'추첨 완료':'추첨 전'}</span></div><p>당첨 정원 ${p.count}명</p>${!p.drawn?button('대상 확인 후 추첨','draw:'+p.id,'primary'):''}</div>`).join('')||empty('상품을 먼저 등록하세요.')}<div class="card"><h3>발송 현황</h3><div class="scroll"><table><thead><tr><th>당첨번호</th><th>상품</th><th>발송 상태</th><th>처리</th></tr></thead><tbody>${a.winners.map(w=>`<tr><td>${esc(w.id.slice(0,8))}</td><td>${esc(w.prize_name)}</td><td>${esc(states[w.status])}</td><td>${button('상태 변경','delivery:'+w.id)}</td></tr>`).join('')}</tbody></table></div>${note('CSV를 외부 상품권 발송 서비스에 업로드한 후 결과를 기록합니다. 자동 발송 API와 수신·사용 확인은 연결되지 않았습니다.')}</div>`}
function messagesAdmin(){return `<h1>소통·현장 대응</h1><div class="actions">${button('업무 알림 작성','add-staff-notice','primary')}</div><div class="grid2"><div class="card"><h3>유형별 부스 문의</h3>${S.admin.inquiries.map(i=>`<div class="bubble"><div class="row">${tag(i.status)}<span class="tag blue">${esc(i.category)}</span>${i.urgent?'<span class="tag red">긴급</span>':''}</div><p><strong>${esc(i.title)}</strong><br>${esc(i.booth_name)} · ${esc(i.assignee||'미배정')}</p>${button('대화·처리','inquiry:'+i.id)}</div>`).join('')||note('접수된 문의가 없습니다.')}</div><div class="card"><h3>알림 확인 현황</h3>${S.admin.notices.filter(n=>n.target!=='public').map(n=>`<div class="bubble"><strong>${esc(n.title)}</strong><p>${esc(n.body)}</p><p>확인 ${n.confirmed.length} / 대상 ${n.target_count} 부스</p>${n.confirmed.map(c=>`<small>${esc(S.admin.booths.find(b=>b.id===c.booth)?.name)} · ${esc(c.display)} · ${timeLabel(c.created)}</small>`).join('')}</div>`).join('')||note('발송된 업무 알림이 없습니다.')}</div></div>`}
function safetyAdmin(){return `<h1>안전 신고 대응</h1><div class="notice info">신고 접수 활성화 전에 대응 담당자·연락망·운영 절차를 준비하세요. 민감 신고는 피해지원 권한(support)이 있어야 열람할 수 있습니다.</div><div class="actions">${button('일반 안전 신고 조회','load-reports:0')}${button('민감 신고 조회','load-reports:1')}</div>${S.reports.map(r=>`<div class="card"><div class="row">${tag(r.status)}<small>신고번호 ${esc(r.id.slice(0,8))} · ${timeLabel(r.created)}</small></div><h3 style="margin-top:13px">${esc({safety:'일반 안전',harassment:'성희롱·성폭력',camera:'불법촬영 의심'}[r.kind])}</h3><p style="white-space:pre-wrap">${esc(r.location)}<br>${esc(r.body)}</p>${form('report-state',`${select('status','처리 상태',Object.entries(states).filter(([v])=>['received','confirmed','progress','resolved'].includes(v)),r.status)}${area('reply','신고자에게 전달할 답변',r.reply)}${submitButton('조치 기록 저장')}`,r.id)}</div>`).join('')||empty('권한에 맞는 신고 조회 버튼을 선택하세요. 열람 이력이 기록됩니다.')}`}
function reportAdmin(){const a=S.analysis;return `<h1>통계·결과 보고서</h1><div class="actions">${button('분석 새로 불러오기','analysis','primary')}${button('부스 CSV','export:booths')}${button('인쇄·PDF 저장','print')}</div><div class="card"><h3>부스·존 참여 및 평가</h3>${note('존 참여는 부스 합계입니다. 고유 참가 패스와 실제 현장 인원은 다릅니다.')}${boothTable(S.admin.booths)}</div>${a?`<div class="grid2"><div class="card"><h3>전체 설문 집계</h3><p>응답 ${a.responses}건 · 부스 운영 실적 ${a.staff_responses}건</p>${Object.values(a.questions).map(q=>`<div class="bubble"><strong>${esc(q.label)}</strong><p>유효 답변 ${q.count}건${q.total!==null?' · 응답 합계 '+Number(q.total).toLocaleString():''}</p>${Object.entries(q.distribution).map(([k,v])=>`<small>${esc(k)}: ${v}</small>`).join('')}</div>`).join('')}</div><div><div class="card"><h3>탄소·사회적 편익</h3><p>배출량 —　감축량 —　사회적 편익 —</p>${note(esc(a.carbon.reason))}</div><div class="card"><h3>지역경제 · 응답된 본인 지출</h3>${Object.entries(a.spend).map(([k,v])=>`<p>${esc({food:'식음료',lodging:'숙박',shopping:'쇼핑',local_transport:'지역 교통'}[k])}: ${v.sum.toLocaleString()}원 <small>(${v.responses}건)</small></p>`).join('')}${note('응답 자료의 단순 집계입니다. 전체 방문객 확대 추정이나 생산·고용 유발효과는 아닙니다. 탄소 편익과 합산하지 않습니다.')}</div></div></div>`:empty('분석 불러오기를 선택하면 권한을 확인한 뒤 집계합니다.')}`}
function settingsAdmin(){const e=S.admin.event,s=e.settings;return `<h1>행사 설정</h1><div class="grid2"><div class="card">${form('settings',`${field('name','행사명',e.name,'text',true)}${area('description','행사 소개',e.description)}${field('venue','장소',e.venue)}<div class="grid2"><div>${field('start','시작일',e.start,'date')}</div><div>${field('end','종료일',e.end,'date')}</div></div>${select('status','행사 상태',[['draft','준비·비공개'],['public','안내 공개'],['active','운영 중'],['ended','현장 종료'],['archived','보관']],e.status)}${select('survey_gate','설문 참여 자격',[['all','전체 참가자'],['missions','미션 달성자']],s.survey_gate)}${select('entry_gate','추첨 응모 자격',[['all','설문 제출'],['missions','설문 + 미션 달성']],s.entry_gate)}${field('required_missions','응모에 필요한 미션 완료 개수',s.required_missions,'number')}${field('entry_end','응모 마감일',s.entry_end,'date')}${field('safety_phone','현장 안전본부 전화',s.safety_phone)}${check('reporting_enabled','대응 인력·절차 확보 후 앱 신고 접수 활성화',s.reporting_enabled)}${submitButton()}`)}</div><div><div class="card"><h3>키비주얼·테마</h3>${form('theme',`${field('primary','대표 색상',s.primary,'color')}${field('accent','보조 색상',s.accent,'color')}<label>키비주얼 이미지 · 최대 4MB</label><input name="image" type="file" accept="image/png,image/jpeg,image/webp">${submitButton('테마 적용')}`)}</div><div class="card"><h3>운영본부 초대</h3>${form('invite-user',`${field('email','초대 이메일','','email',true)}${select('role','권한',[['content','콘텐츠'],['operations','현장 운영'],['survey','설문·추첨'],['safety','일반 안전'],['support','피해지원·민감 신고'],['analyst','분석'],['owner','행사 총괄']],'operations')}${submitButton('초대 링크 생성')}`)}</div><div class="card"><h3>외부 연동 상태</h3>${note('지도·날씨·번역 API: 미연결<br>상품권: 수동 CSV 발송<br>한국어·영어 기본 메뉴 제공, 행사 콘텐츠 영어 번역은 미연결 안내<br>홈페이지: 읽기 전용 공개 API 및 위젯 경로 제공')}${button('홈페이지 삽입 코드','widget-code')}${button('작업 이력','audit')}</div><div class="card"><h3>개인정보 삭제</h3>${note('연락처와 설문 원자료를 삭제합니다. 통계 산출·파일 보관 정책을 먼저 확인하세요. 이 작업은 되돌릴 수 없습니다.')}${button('삭제 절차','purge')}</div></div></div>`}
async function adminRender(){const pages={dashboard,booths:boothsAdmin,content:contentAdmin,missions:missionsAdmin,draw:drawAdmin,messages:messagesAdmin,safety:safetyAdmin,reports:reportAdmin,settings:settingsAdmin};adminShell((pages[S.page]||dashboard)())}
async function loadStaff(){S.staff=await api(ep('booth-data')+'?booth='+encodeURIComponent(S.me.booth.id))}
function staffRender(){const b=S.staff.booth;const content=staffBody();$('#app').innerHTML=`<div class="app-wrap">${intro()}<section class="device"><header class="app-header"><strong>부스 관리</strong>${button('로그아웃','logout','text-btn')}</header><main class="page"><div class="staff-top"><h3>${esc(b.code)} ${esc(b.name)}</h3><small>${esc(b.zone_name)} · ${esc(S.me.display)}</small><label>운영 상태</label><select id="staff-status">${options([['open','운영 중'],['paused','일시 중단'],['closed','운영 종료']],b.status)}</select>${note('일시 중단·종료 상태에서는 QR 인증이 차단됩니다.')}</div><nav class="staff-nav">${[['staff-home','현황'],['staff-info','부스 정보'],['staff-qr','QR'],['staff-messages','소통'],['staff-survey','종료 설문']].map(([p,l])=>button(l,'staff-nav:'+p,S.page===p?'active':'')).join('')}</nav>${content}</main></section></div>`}
function staffBody(){const b=S.staff.booth;if(S.page==='staff-info')return `<h2>부스 정보</h2><p>${b.approved?'승인된 부스':'검토 대기 부스'}</p>${form('staff-info',`${area('description','소개·체험 내용',b.description)}${submitButton('소개 수정')}`)}${note('부스명·존·위치는 운영본부에 변경 요청을 보내 주세요.')}`;if(S.page==='staff-qr')return `<h2>참가 인증 QR</h2><div class="card"><h3>${esc(b.name)}</h3>${button('QR 보기·인쇄','staff-qr','primary full')}${note('관리 전용 QR와 공통 비밀번호를 참가자 출력물에 넣지 마세요.')}</div>${button('관리 접속 주소 확인','staff-manager-link')}`;if(S.page==='staff-messages')return `<h2>운영본부 소통</h2>${S.staff.notices.map(n=>`<div class="card"><span class="tag ${n.confirmation?'':'pink'}">${n.confirmation?'확인 완료':'미확인'}</span><h3 style="margin-top:12px">${esc(n.title)}</h3><p>${esc(n.body)}</p>${n.ack?(n.confirmation?note(esc(n.confirmation.display)+' · '+timeLabel(n.confirmation.created)):button('확인했습니다','ack:'+n.id,'primary')):''}</div>`).join('')||note('새 업무 알림이 없습니다.')}<div class="card"><h3>문의하기</h3>${form('inquiry',`${select('category','용건',['시설·장비','통신·시스템','물품·지원','운영 문의','안전','민원·분쟁','기타'].map(x=>[x,x]),'시설·장비')}${check('urgent','긴급 요청')}${field('title','제목','','text',true)}${area('body','내용','',true)}${submitButton('문의 보내기')}`)}</div>${S.staff.inquiries.map(i=>`<div class="card">${tag(i.status)}<h3 style="margin-top:10px">${esc(i.title)}</h3><p>${esc(i.category)} · ${esc(i.assignee||'담당자 배정 전')}</p>${button('대화 보기','inquiry:'+i.id)}</div>`).join('')}`;if(S.page==='staff-survey')return `<h2>부스 운영 실적 설문</h2>${note('부스당 한 응답을 공동 작성합니다. 지출·사용량은 부스 전체 기준입니다. 모르는 수치는 비워두세요. 재제출하면 이전 실적을 갱신합니다.')}${form('staff-survey',`${field('transport','운송·이동 교통수단')}${[['distance_km','왕복 이동 거리(km)'],['staff_count','운영 인원'],['printing','인쇄물 사용 장수'],['disposable','일회용품 사용 개수'],['reusable','다회용품 사용 횟수'],['local_purchase','지역 내 구매·임차(원)'],['local_hiring','지역 인력 고용비(원)'],['lodging','지역 숙박비(원)'],['food','지역 식비(원)']].map(([k,l])=>field(k,l,'','number')).join('')}${submitButton('실적 제출')}`)}`;return `<div class="stats">${stat('오늘 참여',b.today)}${stat('누적 참여',b.total)}${stat('평균 별점',b.ratings.average??'—')}</div>${note('인증 패스 기준 · 평가 '+b.ratings.count+'건 · 갱신 '+timeLabel(new Date().toISOString()))}<div class="card"><h3>별점 분포</h3><div class="chart">${[1,2,3,4,5].map(n=>`<div class="bar" style="height:${Math.max(3,(b.ratings.distribution[n]||0)/Math.max(1,b.ratings.count)*100)}%"><small>${n}점 ${b.ratings.distribution[n]||0}</small></div>`).join('')}</div></div><div class="actions">${button('인증 QR 출력','staff-qr','primary')}${button('부스 정보 수정','staff-nav:staff-info')}</div>${S.staff.notices.filter(n=>!n.confirmation).slice(0,3).map(n=>`<div class="card"><h3>운영본부 알림</h3><p>${esc(n.title)}</p>${n.ack?button('확인했습니다','ack:'+n.id,'pink-btn'):''}</div>`).join('')}`}
async function boot(){try{const path=location.pathname;if(path==='/invite'){await inviteView();return}if(path==='/register'){await registerView();return}if(path==='/manage'){S.mode='admin';const status=await api('/api/status');if(status.setup_required){loginView(true);return}if(!token){loginView();return}try{S.me=await api('/api/me')}catch{token='';sessionStorage.removeItem('festival_management_token');loginView();return}if(S.me.kind!=='admin'){loginView();return}S.event=S.me.events[0]?.id;S.page='dashboard';if(!S.event){$('#app').innerHTML=`<section class="login"><h1>관리할 행사가 없습니다.</h1>${button('첫 행사 개설','new-event','primary')}</section>`;return}await refreshAdmin();await adminRender();startPolling();return}if(path==='/booth'||path.startsWith('/bm/')){S.mode='staff';if(!token){staffLogin();return}try{S.me=await api('/api/me')}catch{staffLogin();return}if(S.me.kind!=='booth'){staffLogin();return}S.event=S.me.booth.event;S.page='staff-home';await loadStaff();staffRender();startPolling();return}S.mode='participant';let event=path.startsWith('/e/')?path.split('/')[2]:null;if(path.startsWith('/b/')){const info=await api('/api/qr-info/'+path.split('/')[2]);event=info.event;S.qr=path.split('/')[2];S.booth=info;S.page='certify'}if(!event){const events=await api('/api/events');event=events[0]?.id}if(!event){$('#app').innerHTML=`<section class="login"><h1>공개된 행사가 없습니다.</h1><a href="/manage">운영본부 로그인</a></section>`;return}S.event=event;await loadPublic();if(S.qr)S.booth={...S.data.booths.find(b=>b.id===S.booth.id),...S.booth};if(new URLSearchParams(location.search).get('widget')==='1'){renderWidget();return}await publicRender();startPolling()}catch(e){$('#app').innerHTML=`<section class="login"><h1>화면을 열 수 없습니다.</h1><p>${esc(e.message)}</p><a href="/">행사 홈</a> · <a href="/manage">운영본부</a></section>`}}
function startPolling(){clearInterval(S.poll);S.poll=setInterval(async()=>{if(document.hidden||!$('#modal').hidden||$$('input:focus,textarea:focus,select:focus').length)return;try{if(S.mode==='admin'&&['dashboard','messages'].includes(S.page)){await refreshAdmin();await adminRender()}else if(S.mode==='staff'&&['staff-home','staff-messages'].includes(S.page)){await loadStaff();staffRender()}else if(S.mode==='participant'){S.data=await api('/api/events/'+S.event);if(['certify','home','safety','mine'].includes(S.page)){if(S.page==='certify'&&S.booth){const b=S.data.booths.find(x=>x.id===S.booth.id);if(b)S.booth=b}S.pass=await api(ep('pass'));await publicRender()}}}catch{/* last data remains visible; next poll retries without discarding input */}},10000)}
function renderWidget(){$('#app').innerHTML=`<main class="page" style="max-width:1100px;margin:auto"><h2>${esc(S.data.event.name)}</h2><div class="grid3">${S.data.booths.map(b=>`<a class="card" target="_blank" rel="noopener" href="/e/${esc(S.event)}"><span class="tag">${esc(b.zone_name)}</span><h3 style="margin-top:12px">${esc(b.name)}</h3><p>${esc(b.description)}</p></a>`).join('')}</div></main>`}
async function handleAction(a){
 if(a==='close'){closeModal();return}
 if(a.startsWith('nav:'))return navigate(a.slice(4));
 if(a==='language'){S.lang=S.lang==='ko'?'en':'ko';localStorage.setItem('festival_lang',S.lang);await publicRender();if(S.lang==='en')toast('Basic navigation is in English. Content translation API is not configured yet.');return}
 if(a==='other-languages'){modal('언어 안내 · Languages',`<p>한국어·영어 기본 메뉴를 제공합니다. 행사 콘텐츠 번역 API는 아직 연결되지 않았습니다.</p><p>For other languages, use Chrome’s “Translate page”. Automatic translation may differ from the original. Text inside map images may not translate.</p>${note('Chrome 메뉴에서 번역을 선택하세요. 브라우저·버전에 따라 위치가 다를 수 있습니다.')}`);return}
 if(a==='ack-pass'){localStorage.setItem('festival_notice_ack','1');closeModal();S.pass=await api(ep('pass'),'POST',{});if(S.page==='survey')S.survey=await api(ep('survey'));await publicRender();return}
 if(a==='choose-event'){const es=await api('/api/events');modal('행사 선택',es.map(e=>`<p><a href="/e/${esc(e.id)}">${esc(e.name)}</a></p>`).join(''));return}
 if(a==='notices'){modal('전체 공지',S.data.notices.map(n=>`<div class="card"><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p>${note(timeLabel(n.created))}</div>`).join('')||empty('공지 없음'));return}
 if(a.startsWith('program-date:')){S.filter=a.slice(13);await publicRender();return}
 if(a.startsWith('program:')){const p=S.data.programs.find(p=>p.id===a.slice(8));if(!p)return;modal(p.title,`<span class="tag blue">${esc(p.category)}</span><p>${esc(p.date)} ${esc(p.time)}<br>${esc(p.place)}</p><p>${esc(p.description)}</p>${p.url?`<a href="${esc(p.url)}" target="_blank" rel="noopener">외부 신청 페이지로 이동 ↗</a>`:''}<div class="actions">${button('위치 보기','program-location:'+p.id,'primary')}${button('관심 일정 저장','bookmark:'+p.id)}</div>`);return}
 if(a.startsWith('program-location:')){const p=S.data.programs.find(p=>p.id===a.slice(17));S.mapBuilding=p?.building||'outdoor';return navigate('map')}
 if(a.startsWith('bookmark:')){const id=a.slice(9),key='festival_bookmarks_'+S.event;let list=JSON.parse(localStorage.getItem(key)||'[]');const had=list.includes(id);list=had?list.filter(x=>x!==id):[...list,id];localStorage.setItem(key,JSON.stringify(list));toast(had?'관심 일정에서 해제했습니다.':'현재 브라우저에 관심 일정을 저장했습니다.');return}
 if(a.startsWith('booth:')){S.booth=S.data.booths.find(b=>b.id===a.slice(6));return navigate('booth')}
 if(a.startsWith('location:')){const b=S.data.booths.find(b=>b.id===a.slice(9));S.booth=b;S.mapBuilding=b?.building||'outdoor';await navigate('map');return}
 if(a.startsWith('zoom:')){const v=a.slice(5);S.mapZoom=v==='reset'?1:Math.min(3,Math.max(1,S.mapZoom+(v==='+'?.3:-.3)));await publicRender();return}
 if(a==='gps'){if(!navigator.geolocation)throw Error('현재 브라우저에서 위치 기능을 사용할 수 없습니다.');navigator.geolocation.getCurrentPosition(p=>{S.gps={lat:p.coords.latitude,lng:p.coords.longitude,accuracy:p.coords.accuracy};const nodes=S.data.theme.outdoor_nodes||[];if(nodes.length){const nearest=[...nodes].sort((a,b)=>distance(a,S.gps)-distance(b,S.gps))[0];if(distance(nearest,S.gps)>200){toast('등록된 행사장 보행로와 현재 위치가 멉니다. 출발지를 직접 선택해 주세요.');return}$('#f-route-from').value=nearest.id}toast('위치를 확인했습니다. 정확도 약 '+Math.round(p.coords.accuracy)+'m. 가까운 보행 지점을 출발지로 제안합니다.');},()=>toast('위치를 확인하지 못했습니다. 출발지를 직접 선택해 주세요.'),{timeout:10000,enableHighAccuracy:true});return}
 if(a==='route'){const nodes=S.data.theme.outdoor_nodes||[],edges=S.data.theme.outdoor_edges||[];const from=$('#f-route-from').value,to=$('#f-route-to').value;const result=shortestRoute(nodes,edges,from,to);if(!result)throw Error('연결된 보행 경로가 없습니다. 현장 안내를 확인하세요.');$('#route-result').innerHTML=`<div class="notice info">${result.path.map(id=>esc(nodes.find(n=>n.id===id).name)).join(' → ')}<br>약 ${Math.round(result.distance)}m · ${Math.max(1,Math.ceil(result.distance/65))}분${from===to?' · 출발지와 도착지가 같습니다.':''}</div>`;drawRoute(nodes,result);return}
 if(a.startsWith('rate:')){S.rating=Number(a.slice(5));await publicRender();return}
 if(a==='certify'||a==='certify-skip'){if(!await ensurePass())return;if(!S.qr)throw Error('현장의 부스 인증 QR로 접속해 주세요.');await api(ep('certify'),'POST',{qr:S.qr,score:a==='certify'?S.rating:null});S.pass=await api(ep('pass'));S.page='certified';await publicRender();return}
 if(a.startsWith('mission:')){const m=S.pass.missions.find(m=>m.id===a.slice(8));if(!m)return;let action='';if(['quiz','text'].includes(m.kind)){action=form('mission-answer',`${m.kind==='quiz'?`<p>${esc(m.question)}</p>`:''}${area('answer',m.kind==='quiz'?'정답':'수행 내용','',true)}${submitButton(m.kind==='quiz'?'정답 확인':'검토 요청')}`,m.id)}else action=button('부스 찾기','nav:map','primary');modal(m.title,`<p>${esc(m.description)}</p><p>진행 ${m.progress} / ${m.target}</p><progress value="${m.progress}" max="${m.target}"></progress>${note('별도 신청 없이 기간 내 실적을 자동 반영합니다.')}${action}`);return}
 if(a.startsWith('report:')){if(!await ensurePass())return;S.reportKind=a.slice(7);return navigate('report')}
 if(a==='logout'){try{await api('/api/logout','POST',{})}catch{}token='';sessionStorage.removeItem('festival_management_token');location.href=S.mode==='staff'?'/booth':'/manage';return}
 if(a.startsWith('admin-nav:')){S.page=a.slice(10);S.reports=[];closeModal();await refreshAdmin();await adminRender();window.scrollTo(0,0);return}
 if(a==='admin-refresh'){await refreshAdmin();await adminRender();toast('현황을 갱신했습니다.');return}
 if(a==='open-event'){window.open('/e/'+S.event,'_blank','noopener');return}
 if(a==='new-event'){modal('행사 개설',form('new-event',`${field('name','행사명','','text',true)}${area('description','행사 소개')}${field('venue','장소')}${field('start','시작일','','date')}${field('end','종료일','','date')}${S.me?.events.length?select('copy','설정 복제',[['','새로 만들기'],...S.me.events.map(e=>[e.id,e.name])],''):''}${note('존·부스·지도·미션·프로그램·설문 문항을 복제합니다. 부스는 미승인·종료, 미션·설문은 비공개로 생성합니다. 담당자 접근 정보·실적·응답·연락처는 복사하지 않습니다. 날짜·장소·동의문을 재확인하세요.')}${submitButton('비공개 행사 생성')}`));return}
 if(a==='add-zone'){modal('존 추가',form('zone',`${field('name','존 이름','','text',true)}${field('color','대표 색상','#00a3c4','color')}${area('description','소개')}${submitButton('존 추가')}`));return}
 if(a==='registration-link'){modal('부스 등록 링크',`<p class="word-break">${esc(location.origin+'/register?event='+S.event)}</p>${note('부스 담당자가 존을 선택하고 정보를 제출하면 검토 대기로 등록됩니다.')}${button('링크 복사','copy-register','primary')}`);return}
 if(a==='copy-register'){await navigator.clipboard.writeText(location.origin+'/register?event='+S.event);toast('복사했습니다.');return}
 if(a.startsWith('edit-booth:')){const b=S.admin.booths.find(b=>b.id===a.slice(11));modal('부스 정보 수정',form('admin-booth',`${field('name','부스명',b.name,'text',true)}${select('zone','존',S.admin.zones.map(z=>[z.id,z.name]),b.zone)}${field('code','부스 번호',b.code)}${field('building','건물 이름',b.building)}${area('description','소개',b.description)}<div class="grid2"><div>${field('x','이미지 X 위치 (%)',b.x,'number')}</div><div>${field('y','이미지 Y 위치 (%)',b.y,'number')}</div></div>${check('approved','공개 승인',b.approved)}${submitButton()}`,b.id));return}
 if(a.startsWith('booth-access:')){const bid=a.slice(13);const r=await api(ep('booth-access'),'POST',{booth:bid});S.accessBooth={bid,...r};modal('부스 QR·공동 관리',`<div class="notice">관리 주소는 담당자에게만 전달하세요. 비밀번호는 QR에 포함되지 않습니다.</div><p class="word-break"><strong>관리 주소</strong><br>${esc(location.origin+'/bm/'+r.manager)}</p><p class="word-break"><strong>참가 인증 주소</strong><br>${esc(location.origin+'/b/'+r.qr)}</p>${button('인증 QR 보기·다운로드','qr-admin:'+bid,'primary')}${form('reset-booth',`${field('password','새 공통 비밀번호 · 10자 이상','','password',true)}${note('비밀번호 변경 시 해당 부스의 모든 기존 관리 접속이 해제됩니다.')}${submitButton('비밀번호 초기화')}`,bid)}`);return}
 if(a.startsWith('qr-admin:')){await qrModal(a.slice(9));return}
 if(a==='map-editor'){const maps=S.admin.event.settings.building_maps||[];modal('통합 평면도 등록·배치',`${form('map-image',`${field('name','건물명','','text',true)}<label>모든 층이 구분된 통합 평면도 이미지</label><input name="image" type="file" accept="image/png,image/jpeg,image/webp" required>${note('건물별 이미지 한 장을 사용합니다. 등록 후 배치 편집에서 부스를 선택하고 평면도를 클릭해 위치를 지정합니다.')}${submitButton('이미지 등록')}`)}${maps.map(m=>`<div class="card"><h3>${esc(m.name)}</h3><img style="width:100%;max-height:240px;object-fit:contain" src="${esc(m.image)}" alt="통합 평면도">${button('부스 위치 배치','place-map:'+encodeURIComponent(m.name))}</div>`).join('')}<p>${button('야외 보행로 데이터','outdoor-editor')}</p>${note('위성지도 위 이미지 정렬·드래그 배치·자동 실내외 전환은 아직 구현하지 않았습니다.')}`);return}
 if(a.startsWith('place-map:')){const name=decodeURIComponent(a.slice(10));const m=S.admin.event.settings.building_maps.find(m=>m.name===name);if(!m)return;S.placeBuilding=name;modal('통합 평면도 부스 배치',`${note('부스를 선택하고 평면도에서 위치를 클릭하세요. 층 선택 없이 한 이미지에서 배치합니다.')}<div class="map-canvas"><div class="map-inner" id="placement-map" style="min-height:0;cursor:crosshair"><img src="${esc(m.image)}" alt="${esc(m.name)} 통합 평면도">${S.admin.booths.filter(b=>b.building===name).map(b=>`<span class="map-marker" style="pointer-events:none;left:${b.x}%;top:${b.y}%">${esc(b.code||b.name)}</span>`).join('')}<span id="placement-marker" class="map-marker active" style="left:50%;top:50%;pointer-events:none">선택 위치</span></div></div>${form('place-booth',`${select('booth','배치할 부스',S.admin.booths.map(b=>[b.id,(b.code||'')+' '+b.name]),'')}<div class="grid2"><div>${field('x','X 위치 (%)',50,'number')}</div><div>${field('y','Y 위치 (%)',50,'number')}</div></div>${submitButton('부스 위치 저장')}`)}`);return}
 if(a==='outdoor-editor'){modal('야외 보행로 등록',form('outdoor',`${area('nodes','지점 JSON',JSON.stringify(S.admin.event.settings.outdoor_nodes,null,2))}${area('edges','연결 JSON',JSON.stringify(S.admin.event.settings.outdoor_edges,null,2))}${note('지점: {id,name,lat,lng}, 연결: {from,to,closed:false}. 등록된 통로만 경로 계산에 사용합니다.')}${submitButton('보행로 저장')}`));return}
 if(a==='add-program'){modal('프로그램 추가',form('program',`${field('title','프로그램명','','text',true)}${area('description','소개·참여 방법')}${field('date','날짜',S.admin.event.start,'date',true)}${field('time','시작 시각','11:00','time',true)}${field('place','장소명','','text',true)}${field('building','건물명')}${select('category','분야',['세미나','공연','체험','전시'].map(v=>[v,v]),'세미나')}${field('url','외부 신청 링크 · 선택','','url')}${submitButton('등록')}`));return}
 if(a==='add-public-notice'||a==='add-staff-notice'){const staff=a==='add-staff-notice';modal(staff?'업무 알림 작성':'전체 공지 작성',form('notice',`${staff?select('target','발송 대상',[['all','전체 부스'],['zone','특정 존'],['booth','선택 부스']],'all'):'<input type="hidden" name="target" value="public">'}<div id="notice-targets"></div>${field('title','제목','','text',true)}${area('body','내용','',true)}${select('severity','중요도',[['normal','일반'],['important','중요'],['urgent','긴급']],'normal')}${staff?check('ack','확인 버튼 제공',true):''}${submitButton(staff?'업무 알림 발송':'전체 공지 발행')}`));return}
 if(a==='add-mission'){modal('미션 개설',form('mission',`${field('title','미션명','','text',true)}${area('description','설명')}${select('kind','완료 조건',[['booths','서로 다른 부스 N개 · 선택 시 지정 부스 내'],['zone','지정 존 안의 부스 N개'],['zones','서로 다른 존 N개'],['quiz','퀴즈 정답'],['text','글 제출·운영자 검토']],'booths')}${field('target','필요 개수',1,'number')}<label>대상 부스·존 ID · 쉼표 구분, 자유 탐방은 비움</label><input name="refs" placeholder="부스·존 ID"><div class="hint">${S.admin.zones.map(z=>esc(z.name)+': '+esc(z.id)).join('<br>')}</div>${field('start','시작일',S.admin.event.start,'date')}${field('end','종료일',S.admin.event.end,'date')}${field('question','퀴즈 질문 · 퀴즈 유형만')}${field('answer','퀴즈 정답 · 참가자에게 비공개')}${check('published','즉시 공개',true)}${submitButton('미션 생성')}`));return}
 if(a==='edit-survey'){S.questions=structuredClone(S.admin.survey?.questions||[]);surveyEditor();return}
 if(a==='templates-add'){const names=$$('[name=template]:checked').map(x=>x.value);const r=await api(ep('templates'),'POST',{names});for(const q of r.questions)if(!S.questions.some(x=>x.id===q.id))S.questions.push(q);renderQuestionEditor();toast('중복을 제외하고 문항을 추가했습니다.');return}
 if(a==='parse-survey'){const r=await api(ep('parse-survey'),'POST',{text:$('#survey-raw').value});S.questions.push(...r.questions);renderQuestionEditor();toast(r.notice);return}
 if(a.startsWith('question-remove:')){S.questions=S.questions.filter(q=>q.id!==a.slice(16));renderQuestionEditor();return}
 if(a==='review-missions'){const answers=await api(ep('review-answers'));modal('제출형 미션 검토',answers.map(a=>`<div class="card"><h3>${esc(a.title)}</h3><p>${esc(a.answer)}</p><small>${a.approved?'승인':'검토 대기'}</small>${form('review-answer',`<input type="hidden" name="participant" value="${esc(a.participant)}"><input type="hidden" name="mission" value="${esc(a.mission)}">${check('approved','승인',a.approved)}${submitButton('검토 저장')}`)}</div>`).join('')||empty('검토할 제출물이 없습니다.'));return}
 if(a==='add-prize'){modal('상품 등록',form('prize',`${field('name','모바일 상품권 이름','','text',true)}${field('count','당첨 정원',1,'number',true)}${submitButton('상품 등록')}`));return}
 if(a.startsWith('draw:')){const p=S.admin.prizes.find(p=>p.id===a.slice(5));modal('추첨 확정',`<p>${esc(p.name)} · 최대 ${p.count}명</p><div class="notice">확정 후 같은 상품을 다시 추첨할 수 없습니다. 현재 유효 응모 중 기존 당첨자를 제외하고 무작위 추첨합니다. 응모 마감일 다음 날부터 실행 가능합니다.</div>${button('확인하고 추첨 실행','confirm-draw:'+p.id,'primary full')}`);return}
 if(a.startsWith('confirm-draw:')){const r=await api(ep('draw'),'POST',{prize:a.slice(13),confirmed:true});closeModal();await refreshAdmin();await adminRender();toast(r.count+'명 추첨 완료');return}
 if(a.startsWith('delivery:')){const w=S.admin.winners.find(w=>w.id===a.slice(9));modal('상품권 발송 상태',form('delivery',`${select('status','상태',['ready','requested','sent','failed'].map(v=>[v,states[v]]),w.status)}${area('note','외부 발송번호·실패 사유',w.note)}${submitButton('결과 저장')}`,w.id));return}
 if(a.startsWith('export:')){const kind=a.slice(7);if(kind==='winners'&&!confirm('개인 연락처가 포함된 파일입니다. 발송 담당자만 사용하고 보관 정책을 준수하세요. 내려받을까요?'))return;download(await api(ep('export')+'?kind='+kind),kind==='winners'?'giftcard-winners.csv':'booth-report.csv');return}
 if(a==='analysis'){S.analysis=await api(ep('analysis'));await adminRender();return}
 if(a==='print'){window.print();return}
 if(a==='widget-code'){const code=`<iframe src="${location.origin}/e/${S.event}?widget=1" title="행사 부스 안내" width="100%" height="700" style="border:0" loading="lazy"></iframe>`;modal('홈페이지 삽입 코드',`<textarea readonly style="min-height:160px">${esc(code)}</textarea>${note('현재 보안 정책은 동일 출처 삽입만 허용합니다. 외부 홈페이지를 연결하려면 배포 시 FESTIVAL_EMBED_ORIGINS에 실제 홈페이지의 정확한 출처를 명시해야 합니다. API: /api/events/'+esc(S.event))}`);return}
 if(a==='audit'){const logs=await api(ep('audit'));modal('작업 이력',logs.map(x=>`<div class="bubble audit"><strong>${esc(x.action)}</strong><p>${esc(x.detail)}</p><small>${timeLabel(x.created)} · ${esc(x.actor)}</small></div>`).join(''));return}
 if(a==='purge'){modal('개인정보 삭제',form('purge',`${area('confirmation','삭제 확인 · 행사명을 정확히 입력하세요.')}<div class="notice">설문 원자료·연락처를 삭제하면 복구할 수 없습니다. 백업·다운로드 파일 삭제는 별도 절차입니다. 삭제 후 설문 집계는 다시 만들 수 없으므로 비식별 보고서를 먼저 보관하세요.</div>${submitButton('원자료 삭제')}`));return}
 if(a.startsWith('load-reports:')){S.reports=await api(ep('reports')+'?sensitive='+a.slice(13));await adminRender();return}
 if(a.startsWith('staff-nav:')){S.page=a.slice(10);closeModal();await loadStaff();staffRender();return}
 if(a==='staff-qr'){await qrModal(S.me.booth.id);return}
 if(a==='staff-manager-link'){modal('운영자 전용 접속 주소',`<p class="word-break">${esc(location.origin+'/bm/'+S.staff.booth.manager)}</p>${note('동료 담당자에게 관리 주소와 공통 비밀번호를 별도로 전달하세요. 참가자에게 공개하지 마세요.')}`);return}
 if(a.startsWith('ack:')){await api(ep('ack'),'POST',{booth:S.me.booth.id,notice:a.slice(4)});await loadStaff();staffRender();toast('해당 부스의 확인 완료로 기록했습니다.');return}
 if(a.startsWith('inquiry:')){S.inquiry=a.slice(8);const i=(S.mode==='admin'?S.admin.inquiries:S.staff.inquiries).find(i=>i.id===S.inquiry);if(!i)return;inquiryModal(i);return}
 throw Error('아직 연결되지 않은 동작입니다.');
}
function surveyEditor(){const s=S.admin.survey;modal('행사 전체 설문 편집',`<div class="template-options">${[['satisfaction','행사 만족도'],['carbon','탄소 분석'],['economy','지역경제 분석']].map(([id,n])=>`<label class="check"><input type="checkbox" name="template" value="${id}">${n}</label>`).join('')}</div>${button('선택 표준 문항 추가','templates-add')}<label for="survey-raw">설문 원문 붙여넣기</label><textarea id="survey-raw" placeholder="1. 만족하셨나요?&#10;매우 만족 / 만족 / 보통&#10;&#10;2. 의견을 알려주세요. (선택)"></textarea>${button('질문 자동 구성','parse-survey')}<div id="question-editor"></div>${form('survey-config',`${field('title','설문 제목',s?.title||'행사 전체 설문','text',true)}${field('end','설문 마감일',s?.end||'','date')}${area('consent','검토한 개인정보 안내 · 목적·항목·보관 기간·거부 시 영향',s?.consent||'',true)}${check('published','공개',s?.published)}${note('만 14세 미만 개인정보 설문은 보호자 동의 확인 기능 준비 전까지 차단합니다. 추첨 응모 연락처 입력과 동의 항목은 참가자 설문에 별도로 표시됩니다.')}${submitButton('설문 저장')}`)}`);renderQuestionEditor()}
function renderQuestionEditor(){const root=$('#question-editor');if(!root)return;root.innerHTML=S.questions.map((q,i)=>`<div class="card"><strong>${i+1}. ${esc(q.label)}</strong>${q.review?'<span class="tag pink">자동 인식 검토 필요</span>':''}<label>질문 문구</label><input data-question="${esc(q.id)}" data-key="label" value="${esc(q.label)}"><label>유형</label><select data-question="${esc(q.id)}" data-key="type">${options([['text','주관식'],['choice','단일 선택'],['multi','복수 선택'],['number','숫자'],['rating','5점 척도']],q.type)}</select>${['choice','multi'].includes(q.type)?`<label>선택지 · 한 줄에 하나</label><textarea data-question="${esc(q.id)}" data-key="options">${esc((q.options||[]).join('\n'))}</textarea>`:''}<label class="check"><input type="checkbox" data-question="${esc(q.id)}" data-key="required" ${q.required?'checked':''}>필수 응답</label>${button('문항 삭제','question-remove:'+q.id,'text-btn')}</div>`).join('')}
function inquiryModal(i){modal(i.title,`<div class="row">${tag(i.status)}<span class="tag blue">${esc(i.category)}</span></div>${i.messages.map(m=>`<div class="bubble ${m.sender==='admin'?'admin-msg':''}"><small>${esc(m.display)} · ${timeLabel(m.created)}</small>${esc(m.body)}</div>`).join('')}${form('message',`${area('body','답변','',true)}${submitButton('메시지 전송')}`,i.id)}${S.mode==='admin'?form('inquiry-state',`${select('status','처리 상태',['received','confirmed','progress','resolved'].map(v=>[v,states[v]]),i.status)}${field('assignee','담당자',i.assignee)}${submitButton('처리 상태 저장')}`,i.id):''}`)}
async function qrModal(bid){const blob=await api(ep('qr.svg')+'?booth='+bid);if(modalUrl)URL.revokeObjectURL(modalUrl);modalUrl=URL.createObjectURL(blob);const b=S.mode==='staff'?S.staff.booth:S.admin.booths.find(x=>x.id===bid);modal('부스 참여 인증 QR',`<div class="print-title"><h2>${esc(b.name)}</h2><p>${esc(b.code)} · ${esc(b.zone_name)}</p><img class="qr-image" src="${esc(modalUrl)}" alt="부스 참여 인증 QR"><h3>체험 후 QR을 스캔해 참여를 인증해 주세요.</h3><p>Scan after your experience to check in.</p><small>${esc(location.host)} · ${esc(bid.slice(0,8))}</small></div><div class="actions"><a href="${esc(modalUrl)}" download="booth-qr.svg">SVG 다운로드</a>${button('인쇄·PDF 저장','print')}</div>`)}
async function upload(file){if(!file)throw Error('이미지를 선택하세요.');if(file.size>4*1024*1024)throw Error('이미지는 4MB 이하여야 합니다.');const content=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result.split(',')[1]);r.onerror=rej;r.readAsDataURL(file)});return await api(ep('upload'),'POST',{mime:file.type,data:content})}
function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),3000)}
async function onForm(f){const type=f.dataset.form,fd=new FormData(f),d=Object.fromEntries(fd);const id=f.dataset.id;
 if(type==='setup'||type==='login'){const r=await api(type==='setup'?'/api/setup':'/api/login','POST',d);token=r.token;sessionStorage.setItem('festival_management_token',token);await boot();return}
 if(type==='invite'){await api('/api/accept-invite','POST',d);location.href='/manage';return}
 if(type==='booth-login'){const r=await api('/api/booth-login','POST',d);token=r.token;sessionStorage.setItem('festival_management_token',token);await boot();return}
 if(type==='booth-register'){if(!fd.has('consent'))throw Error('운영 목적 정보 제출 동의를 확인하세요.');const r=await api('/api/booth-register','POST',{...d,event:S.event});modal('부스 등록 접수',`<p>${esc(r.message)}</p><p>아래 관리 주소와 설정한 비밀번호를 보관하세요. 동료 담당자도 같은 정보로 접속할 수 있습니다.</p><p class="word-break"><a href="/bm/${esc(r.manager)}">${esc(location.origin+'/bm/'+r.manager)}</a></p>`);f.reset();return}
 if(type==='participant-survey'){if(!S.pass?.participant)throw Error('참가 패스가 없습니다.');if(d.age_group==='under14')throw Error('보호자 동의 절차 준비 전에는 만 14세 미만 개인정보 설문을 제공하지 않습니다.');const normalize=v=>v.replace(/[\s().-]/g,'').replace(/^\+82/,'0');if(d.phone&&normalize(d.phone)!==normalize(d.phone_check))throw Error('연락처를 동일하게 다시 입력해 주세요.');const answers={};for(const q of S.survey.survey.questions){let v=q.type==='multi'?fd.getAll('q_'+q.id):fd.get('q_'+q.id);if(q.type==='rating'&&v)v=Number(v);answers[q.id]=v}if(!confirm('연락처와 응답을 확인하셨나요? 제출 후 이 화면에서 수정할 수 없습니다.'))return;const r=await api(ep('survey'),'POST',{answers,age_group:d.age_group,phone:d.phone,survey_consent:fd.has('survey_consent'),lottery_consent:fd.has('lottery_consent')});S.pass=await api(ep('pass'));await publicRender();const reasons={entered:'설문 제출 및 추첨 응모가 완료되었습니다.',duplicate_contact:'설문은 접수했습니다. 동일 연락처의 기존 유효 응모가 있어 추가 응모에서 제외되었습니다.',conditions:'설문은 접수했습니다. 미션 응모 조건 미달성으로 응모되지 않았습니다.',no_contact:'설문 제출이 완료되었습니다. 추첨에는 응모하지 않았습니다.',closed:'설문은 접수했습니다. 응모 기간은 마감되었습니다.'};modal('제출 결과',`<p>${esc(reasons[r.reason]||'설문이 접수되었습니다.')}</p>${button('내 참여 확인','nav:mine','primary')}`);return}
 if(type==='report'){await api(ep('report'),'POST',{...d,kind:S.reportKind});S.pass=await api(ep('pass'));await navigate('mine');toast('신고가 접수되었습니다. 담당자의 확인과 답변은 별도로 표시됩니다.');return}
 if(type==='mission-answer'){const r=await api(ep('mission-answer'),'POST',{mission:id,answer:d.answer});S.pass=await api(ep('pass'));closeModal();await publicRender();toast(r.approved?'미션 완료!':r.pending?'운영자 검토를 요청했습니다.':'정답이 아닙니다. 다시 확인해 주세요.');return}
 if(type==='new-event'){const r=await api('/api/events','POST',d);S.me=await api('/api/me');S.event=r.id;S.page='settings';closeModal();await refreshAdmin();await adminRender();return}
 if(type==='zone'){await api(ep('zone'),'POST',d)}
 else if(type==='admin-booth'){await api(ep('booth'),'POST',{...d,id,approved:fd.has('approved'),x:Number(d.x),y:Number(d.y)})}
 else if(type==='reset-booth'){await api(ep('booth-access'),'POST',{booth:id,password:d.password})}
 else if(type==='program'){await api(ep('program'),'POST',d)}
 else if(type==='notice'){const refs=fd.getAll('refs');await api(ep('notice'),'POST',{...d,refs,ack:fd.has('ack')})}
 else if(type==='mission'){await api(ep('mission'),'POST',{...d,target:Number(d.target),refs:d.refs.split(',').map(x=>x.trim()).filter(Boolean),published:fd.has('published')})}
 else if(type==='survey-config'){await api(ep('survey-config'),'POST',{...d,questions:S.questions,published:fd.has('published')})}
 else if(type==='review-answer'){await api(ep('review-answer'),'POST',{...d,approved:fd.has('approved')})}
 else if(type==='prize'){await api(ep('prize'),'POST',{...d,count:Number(d.count)})}
 else if(type==='delivery'){await api(ep('delivery'),'POST',{...d,id})}
 else if(type==='settings'){await api(ep('settings'),'POST',{...d,required_missions:Number(d.required_missions),reporting_enabled:fd.has('reporting_enabled')})}
 else if(type==='theme'){let hero=S.admin.event.settings.hero;const image=fd.get('image');if(image?.size)hero=(await upload(image)).url;await api(ep('settings'),'POST',{primary:d.primary,accent:d.accent,hero})}
 else if(type==='map-image'){const r=await upload(fd.get('image'));let maps=structuredClone(S.admin.event.settings.building_maps||[]);maps=maps.filter(m=>m.name!==d.name);maps.push({name:d.name,image:r.url});await api(ep('settings'),'POST',{maps})}
 else if(type==='place-booth'){await api(ep('booth'),'POST',{id:d.booth,building:S.placeBuilding,x:Number(d.x),y:Number(d.y)})}
 else if(type==='outdoor'){let nodes,edges;try{nodes=JSON.parse(d.nodes);edges=JSON.parse(d.edges)}catch{throw Error('JSON 형식을 확인하세요.')}await api(ep('settings'),'POST',{outdoor:{nodes,edges}})}
 else if(type==='invite-user'){const r=await api(ep('invite'),'POST',d);modal('초대 링크 생성',`<p>24시간 동안 유효한 1회용 초대입니다.</p><p class="word-break">${esc(location.origin+'/invite?code='+r.invite)}</p>`);return}
 else if(type==='staff-info'){await api(ep('booth-update'),'POST',{booth:S.me.booth.id,description:d.description})}
 else if(type==='inquiry'){await api(ep('inquiry'),'POST',{...d,booth:S.me.booth.id,urgent:fd.has('urgent')})}
 else if(type==='message'){await api(ep('message'),'POST',{inquiry:id,body:d.body});if(S.mode==='admin')await refreshAdmin();else await loadStaff();const i=(S.mode==='admin'?S.admin.inquiries:S.staff.inquiries).find(i=>i.id===id);inquiryModal(i);return}
 else if(type==='inquiry-state'){await api(ep('inquiry-state'),'POST',{...d,inquiry:id})}
 else if(type==='staff-survey'){const answers={};for(const [k,v]of fd)answers[k]=k==='transport'?v:(v===''?null:Number(v));await api(ep('staff-survey'),'POST',{booth:S.me.booth.id,answers})}
 else if(type==='report-state'){await api(ep('report-state'),'POST',{...d,id});S.reports=[]}
 else if(type==='purge'){if(!confirm('설문 원자료와 연락처를 영구 삭제할까요?'))return;const r=await api(ep('purge-contact'),'POST',d);toast(r.warning)}
 else throw Error('지원하지 않는 양식입니다.');
 closeModal();if(S.mode==='admin'){await refreshAdmin();await adminRender()}else if(S.mode==='staff'){await loadStaff();staffRender()}toast('저장했습니다.');
}
function distance(a,b){const R=6371000,rad=x=>x*Math.PI/180;const dl=rad(b.lat-a.lat),dn=rad(b.lng-a.lng);const x=Math.sin(dl/2)**2+Math.cos(rad(a.lat))*Math.cos(rad(b.lat))*Math.sin(dn/2)**2;return R*2*Math.atan2(Math.sqrt(x),Math.sqrt(1-x))}
function shortestRoute(nodes,edges,from,to){const ds=new Map(nodes.map(n=>[n.id,Infinity])),prev=new Map(),todo=new Set(ds.keys());if(!todo.has(from)||!todo.has(to))return null;ds.set(from,0);while(todo.size){const u=[...todo].reduce((a,b)=>ds.get(a)<ds.get(b)?a:b);if(!Number.isFinite(ds.get(u)))break;todo.delete(u);if(u===to)break;for(const e of edges.filter(e=>!e.closed&&(e.from===u||e.to===u))){const v=e.from===u?e.to:e.from;if(!todo.has(v))continue;const len=distance(nodes.find(n=>n.id===u),nodes.find(n=>n.id===v));if(ds.get(u)+len<ds.get(v)){ds.set(v,ds.get(u)+len);prev.set(v,u)}}}if(!Number.isFinite(ds.get(to)))return null;const path=[to];while(path[0]!==from){const p=prev.get(path[0]);if(!p)return null;path.unshift(p)}return {path,distance:ds.get(to)}}
function drawRoute(nodes,r){const lat=nodes.map(n=>Number(n.lat)),lng=nodes.map(n=>Number(n.lng)),minX=Math.min(...lng),maxX=Math.max(...lng),minY=Math.min(...lat),maxY=Math.max(...lat);const xy=n=>[30+(n.lng-minX)/(maxX-minX||1)*270,230-(n.lat-minY)/(maxY-minY||1)*200];$('#outdoor-canvas').innerHTML=`<svg viewBox="0 0 330 270" role="img" aria-label="등록된 보행로 경로 개략도" style="width:100%;height:270px;background:#f0f8f4">${S.data.theme.outdoor_edges.filter(e=>!e.closed).map(e=>{const a=xy(nodes.find(n=>n.id===e.from)),b=xy(nodes.find(n=>n.id===e.to));return `<line x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}" stroke="#c1d9d5" stroke-width="5"/>`}).join('')}<polyline points="${r.path.map(id=>xy(nodes.find(n=>n.id===id)).join(',')).join(' ')}" fill="none" stroke="#075de5" stroke-width="4"/>${r.path.map(id=>{const n=nodes.find(n=>n.id===id),p=xy(n);return `<circle cx="${p[0]}" cy="${p[1]}" r="5" fill="#075de5"/><text x="${p[0]}" y="${p[1]-12}" text-anchor="middle" font-size="9">${esc(n.name)}</text>`}).join('')}</svg><div class="map-label">보행로 개략도 · 위성지도 아님</div>`}
document.addEventListener('click',async e=>{const placement=e.target.closest('#placement-map');if(placement){const r=placement.getBoundingClientRect(),x=Math.round((e.clientX-r.left)/r.width*1000)/10,y=Math.round((e.clientY-r.top)/r.height*1000)/10;$('#f-x').value=x;$('#f-y').value=y;$('#placement-marker').style.left=x+'%';$('#placement-marker').style.top=y+'%';return}const b=e.target.closest('[data-action]');if(!b)return;e.preventDefault();if(b.disabled)return;const action=b.dataset.action;const wasDisabled=b.disabled;try{b.disabled=true;await handleAction(action)}catch(err){toast(err.message)}finally{if(b.isConnected)b.disabled=wasDisabled}});
document.addEventListener('submit',async e=>{const f=e.target.closest('form[data-form]');if(!f)return;e.preventDefault();const buttons=[...f.querySelectorAll('button[type=submit]')];buttons.forEach(b=>b.disabled=true);try{await onForm(f)}catch(err){toast(err.message)}finally{buttons.forEach(b=>b.disabled=false)}});
document.addEventListener('input',e=>{const q=e.target.dataset.question;if(q){const item=S.questions.find(x=>x.id===q);const key=e.target.dataset.key;if(item)item[key]=key==='required'?e.target.checked:key==='options'?e.target.value.split('\n').filter(Boolean):e.target.value;return}if(e.target.id==='booth-search'){S.filter=e.target.value;clearTimeout(S.searchTimer);S.searchTimer=setTimeout(async()=>{const position=e.target.selectionStart;await publicRender();const input=$('#booth-search');input?.focus();input?.setSelectionRange(position,position)},350)}if(e.target.id==='admin-booth-search')filterAdminBooths()});
document.addEventListener('change',async e=>{try{const id=e.target.id;if(id==='zone-filter'){S.zone=e.target.value;await publicRender()}if(id==='building-filter'){S.mapBuilding=e.target.value;await publicRender()}if(id==='event-switch'){S.event=e.target.value;await refreshAdmin();await adminRender()}if(id==='admin-zone-filter')filterAdminBooths();if(id==='staff-status'){const status=e.target.value;if(status!=='open'&&!confirm('인증이 차단됩니다. 운영 상태를 변경할까요?')){e.target.value=S.staff.booth.status;return}await api(ep('booth-update'),'POST',{booth:S.me.booth.id,status});await loadStaff();staffRender();toast('운영 상태를 변경했습니다.')}if(e.target.name==='age_group'){$('#child-notice').innerHTML=e.target.value==='under14'?'<div class="notice">만 14세 미만 개인정보 설문은 보호자 동의 절차 준비 후 제공합니다. 일반 행사 이용은 가능합니다.</div>':''}if(e.target.name==='target'){const v=e.target.value;$('#notice-targets').innerHTML=['zone','booth'].includes(v)?`<label>발송 대상 선택</label>${(v==='zone'?S.admin.zones:S.admin.booths).map(x=>`<label class="check"><input type="checkbox" name="refs" value="${esc(x.id)}">${esc(x.name)}</label>`).join('')}`:''}if(e.target.dataset.key==='type'){const q=S.questions.find(q=>q.id===e.target.dataset.question);q.type=e.target.value;renderQuestionEditor()}}catch(err){toast(err.message)}});
function filterAdminBooths(){const search=$('#admin-booth-search')?.value||'',zone=$('#admin-zone-filter')?.value||'';$('#booth-table').innerHTML=boothTable(S.admin.booths.filter(b=>(!zone||b.zone===zone)&&b.name.includes(search)))}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&!$('#modal').hidden){const els=[...$('#modal').querySelectorAll('button:not(:disabled),input:not(:disabled),select,textarea,a[href]')];if(!els.length)return;const first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
window.addEventListener('offline',()=>toast('연결이 끊겼습니다. 인증·응모·신고는 서버 확인 후 완료됩니다.'));
window.addEventListener('online',()=>toast('연결이 복구되었습니다. 전송에 실패한 작업은 다시 확인해 주세요.'));
boot();

